"""Single-address and bulk email validation (issue #1).

The contract is deliberately literal: exactly one ``@``, a non-empty
local part, a domain containing at least one ``.``, and no whitespace
anywhere.
"""


def check(email: str) -> bool:
    """Return ``True`` when *email* is a structurally valid address.

    Rules:
      - non-string input is invalid;
      - no whitespace anywhere in the address;
      - exactly one ``@``;
      - the local part (before ``@``) is non-empty;
      - the domain (after ``@``) is non-empty and contains at least
        one ``.``.
    """
    if not isinstance(email, str):
        return False
    if any(char.isspace() for char in email):
        return False
    if email.count("@") != 1:
        return False
    local, domain = email.split("@")
    if not local or not domain:
        return False
    return "." in domain


def validate_many(emails: list[str]) -> list[bool]:
    """Return one verdict per input, in order, via :func:`check`."""
    return [check(email) for email in emails]
